    readonly types: Count[];
    readonly tags: Count[];
    readonly vocabulary: { types: string[]; relations: string[]; path?: string };
    readonly broken: { from: string; target: string; relation?: string }[];
    readonly orphans: string[];
    readonly untyped: string[];
    readonly typeDrift: Drift[];
    readonly relationDrift: Drift[];
